import assert from 'node:assert/strict';
import fc from 'fast-check';
import { ProviderContinuity } from '../../source/services/provider-continuity.ts';
import {
  filterChainedModelInput,
  MissingChainedToolOutputError,
  OrphanedChainedToolOutputError,
} from '../../source/lib/chained-input-filter.ts';

const action = fc.record({
  count: fc.integer({ min: 1, max: 4 }),
  selected: fc.integer({ min: 1, max: 4 }),
  reverse: fc.boolean(),
  boundary: fc.constantFrom('keep', 'reset', 'break'),
  output: fc.jsonValue(),
});
export const continuityProperties = [
  {
    name: 'continuity.debt-filter',
    property: fc.property(fc.array(action, { minLength: 1, maxLength: 30 }), (actions) => {
      const continuity = new ProviderContinuity();
      for (const [step, a] of actions.entries()) {
        const ids = Array.from({ length: a.count }, (_, i) => `call-${step}-${i}`);
        const response = `response-${step}`;
        const snapshot = { revision: step + 1, identity: 'snapshot', history: [] };
        continuity.acceptSegment({
          kind: 'committed',
          lastResponseId: response,
          historyCommitted: true,
          snapshot,
          unsettledToolCallIds: [...ids, ids[0]],
        });
        assert.equal(continuity.previousResponseId, response);
        assert.deepEqual(continuity.outstandingToolCallIds, ids, 'lost or duplicated authoritative debt');
        const chosen = ids.slice(0, Math.min(a.selected, ids.length));
        const results = chosen.map((id) => ({ type: 'function_call_output', call_id: id, output: a.output }));
        if (a.reverse) results.reverse();
        const unrelated = { type: 'function_call_output', call_id: `old-${step}`, output: 'old' };
        const input = [
          { type: 'message', role: 'user', content: 'anchor' },
          unrelated,
          ...results,
          { type: 'message', role: 'user', content: 'next' },
        ];
        const request = { input, model: 'probe' };
        const before = structuredClone(request);
        const filtered = filterChainedModelInput(request, {
          toolResultCallIds: continuity.outstandingToolCallIds,
          knownToolCallIds: ids,
        });
        assert.deepEqual(
          filtered,
          { ...request, input: results },
          'filter changed selected output values/order or kept unrelated items',
        );
        assert.deepEqual(request, before, 'filter mutated request');
        assert.throws(
          () => filterChainedModelInput({ input: [] }, { toolResultCallIds: ids, knownToolCallIds: ids }),
          MissingChainedToolOutputError,
        );
        assert.throws(
          () =>
            filterChainedModelInput(
              { input: [unrelated] },
              { toolResultCallIds: [unrelated.call_id], knownToolCallIds: ids },
            ),
          OrphanedChainedToolOutputError,
        );
        // Actual calls in full history independently establish result ownership.
        const full = [
          ...ids.map((id) => ({ type: 'function_call', call_id: id, name: 'probe', arguments: '{}' })),
          ...results,
        ];
        assert.deepEqual(filterChainedModelInput({ input: full }, { toolResultCallIds: chosen }).input, results);
        if (a.boundary === 'keep') {
          assert.equal(continuity.prepareNewTurn(10), false, 'new user turn reused unpaid tool debt');
          assert.equal(continuity.previousResponseId, null);
          assert.deepEqual(continuity.outstandingToolCallIds, []);
        }
        if (a.boundary !== 'keep') {
          const lineage = continuity.lineage;
          if (a.boundary === 'reset') continuity.clear();
          else continuity.breakChaining();
          assert.equal(continuity.previousResponseId, null, 'retired anchor retained');
          assert.deepEqual(continuity.outstandingToolCallIds, [], 'retired tool debt retained');
          if (a.boundary === 'reset') {
            assert.equal(
              continuity.observeCandidate({
                responseId: response,
                lineage,
                identity: { provider: 'probe', endpoint: 'local', model: 'probe' },
                prefix: { revision: step, identity: 'snapshot' },
              }),
              false,
              'stale lineage candidate accepted',
            );
          }
          assert.equal(continuity.previousResponseId, null, 'retired anchor revived');
          assert.deepEqual(continuity.outstandingToolCallIds, []);
        }
      }
    }),
  },
];
import assert from 'node:assert/strict';
import fc from 'fast-check';
import { buildToolLedgerFromJournalEvents } from '../../source/services/conversation/journal-to-ledger.ts';
import { normalizeRunItems } from '../../source/services/conversation/run-item-normalizer.ts';

const unit = fc.record({
  turn: fc.integer({ min: 0, max: 4 }),
  arguments: fc.jsonValue(),
  output: fc.jsonValue(),
  reasoning: fc.option(fc.string(), { nil: null }),
  status: fc.constantFrom('started', 'completed', 'failed', 'aborted', 'unknown'),
});
export const journalProperties = [
  {
    name: 'journal.reconstruction',
    property: fc.property(fc.array(unit, { maxLength: 30 }), (units) => {
      const seqs = new Map();
      const counts = new Map();
      const events = [];
      const expected = new Map();
      for (const u of units) {
        const turnId = `turn-${u.turn}`;
        const callId = `call-${counts.get(turnId) ?? 0}`; // deliberately reused across turns
        counts.set(turnId, (counts.get(turnId) ?? 0) + 1);
        const push = (item) => {
          const seq = (seqs.get(turnId) ?? 0) + 1;
          seqs.set(turnId, seq);
          events.push({ type: 'assistant_journal_item', turnId, seq, item });
        };
        if (u.reasoning !== null)
          push({
            type: 'reasoning',
            text: u.reasoning,
            providerMetadata: { reasoning_content: 'duplicate-private-text', origin: turnId },
          });
        push({ type: 'tool_call', callId, toolName: 'probe', arguments: u.arguments });
        if (u.status !== 'started')
          push({ type: 'tool_result', callId, toolName: 'probe', status: u.status, output: u.output });
        const list = expected.get(turnId) ?? [];
        list.push({ ...u, turnId, callId });
        expected.set(turnId, list);
      }
      const before = structuredClone(events);
      const startedAt = '2026-01-01T00:00:00.000Z';
      const ledger = buildToolLedgerFromJournalEvents(events, startedAt);
      assert.deepEqual(events, before, 'reconstruction mutated journal');
      assert.deepEqual(buildToolLedgerFromJournalEvents(events, startedAt), ledger, 'reconstruction not repeatable');
      const ordered = [...expected.values()].flat();
      assert.equal(ledger.length, units.length, 'lost or merged event identity');
      const identities = new Set();
      ledger.forEach((entry, n) => {
        const e = ordered[n];
        const identity = `${entry.turnId}/${entry.callId}`;
        assert.ok(!identities.has(identity), 'duplicate (turn,call) identity');
        identities.add(identity);
        assert.equal(entry.turnId, e.turnId);
        assert.equal(entry.callId, e.callId);
        assert.equal(entry.toolName, 'probe');
        assert.deepEqual(entry.arguments, e.arguments);
        assert.equal(entry.status, e.status);
        assert.equal(entry.startedAt, startedAt);
        if (e.status !== 'started') {
          assert.deepEqual(entry.output, e.output);
          assert.equal(entry.completedAt, startedAt);
        } else {
          assert.equal(entry.output, undefined);
          assert.equal(entry.completedAt, undefined);
        }
        const normalized = normalizeRunItems(entry.historyItems);
        assert.deepEqual(
          normalized.filter((i) => i.type === 'tool_call').map((i) => i.callId),
          [e.callId],
        );
        assert.deepEqual(
          normalized.filter((i) => i.type === 'tool_result').map((i) => i.callId),
          e.status === 'started' ? [] : [e.callId],
        );
        const reasoning = entry.historyItems.filter((i) => i.type === 'reasoning');
        assert.equal(reasoning.length, e.reasoning === null ? 0 : 1);
        if (e.reasoning !== null) {
          assert.deepEqual(reasoning[0].content, e.reasoning ? [{ type: 'reasoning_text', text: e.reasoning }] : []);
          assert.deepEqual(reasoning[0].providerData, { origin: e.turnId });
        }
      });
      // Returned history payloads are snapshots, not writable views of journal data.
      for (const entry of ledger) if (entry.historyItems?.[0]) entry.historyItems[0].probeMutation = true;
      assert.deepEqual(events, before, 'history aliases persisted event payload');
    }),
  },
];

import assert from 'node:assert/strict';
import fc from 'fast-check';
import { OpenAIResponsesModelWithPromptCacheKey } from '../../source/providers/openai-responses-model.ts';
import { OpenAIChatCompletionsModel } from '../../source/providers/openai-chat-completions-model.ts';
import { toCodexResponsesInput } from '../../source/providers/codex-turn-converter.ts';

const entry = fc.record({
  lane: fc.constantFrom('openai', 'grok', 'chat-a', 'chat-b', 'openai-compatible'),
  origin: fc.constantFrom(null, 'openai', 'codex', 'chat-a', 'chat-b', 'grok'),
  text: fc.string(),
});

/** Capture the real adapter's serialized request at its SDK client boundary. */
async function wireInput(lane, input) {
  if (lane === 'codex') return toCodexResponsesInput(input);
  let captured;
  const responses = lane === 'openai' || lane === 'grok';
  const client = responses
    ? {
        responses: {
          create: async (payload) => {
            captured = payload.input;
            return (async function* () {
              yield { type: 'response.completed', response: { id: 'response', status: 'completed', output: [] } };
            })();
          },
        },
      }
    : {
        chat: {
          completions: {
            create: async (payload) => {
              captured = payload.messages;
              return (async function* () {
                yield { id: 'response', choices: [{ delta: {}, finish_reason: 'stop' }] };
              })();
            },
          },
        },
      };
  const adapter = responses
    ? new OpenAIResponsesModelWithPromptCacheKey(client, 'probe', {}, undefined, undefined, lane)
    : new OpenAIChatCompletionsModel(client, 'probe', undefined, lane);
  for await (const _event of adapter.stream({ input, tools: [] })) {
    /* consume real conversion */
  }
  assert.ok(captured, 'adapter did not reach client boundary');
  return captured;
}

export const opaqueProperties = [
  {
    name: 'opaque.lane-isolation',
    property: fc.asyncProperty(
      fc.array(entry, { maxLength: 30 }),
      fc.constantFrom('openai', 'codex', 'grok', 'chat-a', 'chat-b'),
      async (entries, target) => {
        const lane = target === 'codex' ? 'openai' : target;
        const input = [{ type: 'message', role: 'user', content: [{ type: 'text', text: 'ordinary-user-content' }] }];
        const expected = [];
        entries.forEach((e, n) => {
          const sentinel = `OPAQUE_SENTINEL_${n}_END`;
          const payload =
            e.lane === 'openai' || e.lane === 'grok'
              ? { type: 'reasoning', encrypted_content: sentinel, summary: [] }
              : { reasoning_content: sentinel };
          // Disputed legacy -> Grok policy is intentionally not asserted.
          const omitted = target === 'grok' && e.lane === 'openai-compatible';
          if (!omitted)
            input.push({
              type: 'provider_opaque',
              provider: e.lane,
              ...(target.startsWith('chat-') || e.origin === null ? {} : { sourceProvider: e.origin }),
              item: payload,
            });
          // Every chat opaque payload belongs to its own adjacent assistant group.
          input.push({
            type: 'message',
            role: 'assistant',
            content: [{ type: 'text', text: `ordinary-assistant-${n}:${e.text}` }],
          });
          const laneMatches = e.lane === lane || (target.startsWith('chat-') && e.lane === 'openai-compatible');
          // Backend-origin pins apply at Responses/Codex conversion. Chat lane tags
          // are already configured-provider identities, not shared wire identities.
          const originMatches = target.startsWith('chat-') || e.origin === null || e.origin === target;
          expected.push({ sentinel, survives: !omitted && laneMatches && originMatches, payload });
        });
        const before = structuredClone(input);
        const wire = await wireInput(target, input);
        const json = JSON.stringify(wire);
        assert.ok(json.includes('ordinary-user-content'), 'ordinary user history lost');
        entries.forEach((_, n) =>
          assert.ok(json.includes(`ordinary-assistant-${n}:`), 'ordinary assistant history lost'),
        );
        for (const { sentinel, survives, payload } of expected) {
          const count = json.split(sentinel).length - 1;
          assert.equal(count, survives ? 1 : 0, `opaque sentinel ${sentinel} crossed lane or was lost for ${target}`);
          if (survives && (target === 'openai' || target === 'codex' || target === 'grok'))
            assert.ok(
              wire.some((item) => JSON.stringify(item) === JSON.stringify(payload)),
              'own opaque payload changed',
            );
        }
        assert.deepEqual(input, before, 'adapter mutated opaque input');
      },
    ),
  },
];
