/**
 * Which provider-opaque items a given wire lane may replay.
 *
 * An opaque item is a provider-private payload — encrypted reasoning, a
 * continuity blob, a native compaction marker — that Term2 stores verbatim and
 * hands back to the lane that produced it. Handing one to a *different* lane is
 * never valid: the payload is signed or encrypted for its origin, and the
 * receiving API rejects or misreads it.
 *
 * Two things follow, and they are easy to conflate:
 *
 * 1. **A foreign opaque item must not be sent.** That is a hard rule.
 * 2. **Encountering one is not an error.** It is the ordinary consequence of
 *    switching providers on an existing conversation. The item is inert
 *    baggage; the rest of the history is still perfectly replayable.
 *
 * Term2 used to conflate them and throw on (1), which turned every
 * provider switch on a reasoning-bearing conversation into a dead session — the
 * item stays in history forever, so every subsequent turn threw again. The
 * correct handling is to drop the item and continue. The conversion is lossy,
 * but a provider switch is inherently lossy, and the loss is confined to state
 * the new provider could not have used.
 *
 * The tag is a *lane* identity, not a provider id. The Responses lane tags its
 * items `openai` no matter which configured provider routes to it, because the
 * payload shape is the Responses API's. Chat Completions tags items with the
 * configured provider name, because two providers of the same
 * `openai-compatible` type spell reasoning differently.
 */

/** The lane tag every OpenAI Responses adapter produces and accepts. */
export const OPENAI_RESPONSES_OPAQUE_TAG = 'openai';

/**
 * Grok speaks the Responses wire shape but is a different vendor, so its
 * encrypted reasoning and native items are not interchangeable with OpenAI's.
 * The lane comment above says the tag names the wire shape rather than the
 * provider; that held only while OpenAI and Codex were the sole Responses
 * providers, both of them OpenAI. A second vendor on the same shape needs its
 * own lane, or a provider switch would hand one vendor another's ciphertext.
 */
export const GROK_RESPONSES_OPAQUE_TAG = 'grok';

/**
 * Conversations recorded before Chat Completions opaque items carried the
 * configured provider name were tagged with the shared type. Items from that
 * window still replay on any openai-compatible provider; a genuinely foreign
 * tag is still refused.
 */
export const LEGACY_SHARED_PROVIDER_TAG = 'openai-compatible';

/**
 * Reads the lane tag off either spelling of an opaque item: the
 * `providerOpaque` marker restored onto a replayed provider item, or the
 * `{ type: 'provider_opaque', provider, item }` envelope.
 */
export function providerOpaqueTagOf(item: unknown): string | undefined {
  if (!item || typeof item !== 'object') return undefined;
  const record = item as Record<string, unknown>;
  if (record.type === 'provider_opaque' && typeof record.provider === 'string') return record.provider;
  const marker = record.providerOpaque;
  if (!marker || typeof marker !== 'object' || Array.isArray(marker)) return undefined;
  const provider = (marker as Record<string, unknown>).provider;
  return typeof provider === 'string' ? provider : undefined;
}

/** Reads the backend origin when it was recorded separately from the lane tag. */
export function providerOpaqueSourceOf(item: unknown): string | undefined {
  if (!item || typeof item !== 'object') return undefined;
  const record = item as Record<string, unknown>;
  if (record.type === 'provider_opaque' && typeof record.sourceProvider === 'string') {
    return record.sourceProvider;
  }
  const marker = record.providerOpaque;
  if (!marker || typeof marker !== 'object' || Array.isArray(marker)) return undefined;
  const sourceProvider = (marker as Record<string, unknown>).sourceProvider;
  return typeof sourceProvider === 'string' ? sourceProvider : undefined;
}

/** True when `item` is opaque and belongs to a lane other than `laneTag`. */
export function isForeignProviderOpaque(item: unknown, laneTag: string, targetProvider: string = laneTag): boolean {
  const tag = providerOpaqueTagOf(item);
  if (tag === undefined) return false;
  if (!acceptsProviderOpaqueTag(tag, laneTag)) return true;
  const sourceProvider = providerOpaqueSourceOf(item);
  return sourceProvider !== undefined && sourceProvider !== targetProvider;
}

/** True when a lane may replay an opaque item carrying `tag`. */
export function acceptsProviderOpaqueTag(tag: string, laneTag: string): boolean {
  if (tag === laneTag) return true;
  // The legacy shared tag is only honoured by Chat Completions lanes, which are
  // the only lanes that ever produced it. The Responses lane must not adopt it.
  return laneTag !== OPENAI_RESPONSES_OPAQUE_TAG && tag === LEGACY_SHARED_PROVIDER_TAG;
}

import { isDeepStrictEqual } from 'node:util';
import type { OpenAIRootCheckpointLifecycleObserver } from './openai-root-checkpoint-lifecycle-observer.js';

export type ProviderCheckpointIdentity = {
  provider: string;
  endpoint: string;
  model: string;
};

export type ProviderCheckpointPrefix = {
  revision: number;
  identity: string;
};

export type ProviderCheckpointBinding = {
  identity: ProviderCheckpointIdentity;
  prefix: ProviderCheckpointPrefix;
};

export type ProviderCheckpointRetirement = {
  code: 'reset' | 'superseded' | 'chaining_broken' | 'identity_mismatch' | 'prefix_mismatch';
};

export type ProviderCheckpointSuccessorProof = {
  revision: number;
  identity: string;
  origin?: string;
  history: readonly unknown[];
};

/** Fixed, non-sensitive explanation for why future-selector evidence is unavailable. */
export type ProviderSuccessorEligibilityFailure =
  | 'no_accepted_checkpoint'
  | 'missing_successor_proof'
  | 'lineage_mismatch'
  | 'invalid_planned_snapshot'
  | 'identity_mismatch'
  | 'origin_mismatch'
  | 'revision_not_advanced'
  | 'history_not_extended'
  | 'history_prefix_mismatch';

export type ProviderSuccessorEligibility =
  | { eligible: true }
  | { eligible: false; failure: ProviderSuccessorEligibilityFailure };

export type ProviderCheckpoint = ProviderCheckpointBinding & {
  state: 'candidate' | 'accepted' | 'retired';
  lineage: number;
  responseId: string;
  opaqueState?: unknown;
  /**
   * Immutable authoritative history captured immediately after the response was
   * committed. It is evidence for a future provider-private selector only; it
   * does not affect existing response-ID publication or wire selection.
   */
  successorProof?: ProviderCheckpointSuccessorProof;
  retirement?: ProviderCheckpointRetirement;
};

/** An authoritative Record fact, incorporated before another request is prepared. */
export type AcceptedProviderSegment = {
  kind: 'committed' | 'partial';
  lastResponseId: string | null;
  historyCommitted: boolean;
  snapshot: ProviderCheckpointSuccessorProof;
  unsettledToolCallIds: readonly string[];
};

/**
 * Owns provider-side response chaining state: previousResponseId and
 * whether chaining has been broken (e.g. by transport downgrade).
 *
 * This is the single source of truth for provider continuity. All other
 * collaborators read from this object rather than storing their own copy.
 *
 * ## Chain settlement
 *
 * When a published response issued function calls, the next request must
 * supply matching tool outputs or the chain must be dropped. Outstanding
 * call ids are the local record of that unpaid server debt. Clear them only
 * when a later terminal response replaces them, or when continuity is reset.
 */
export class ProviderContinuity {
  #previousResponseId: string | null = null;
  #chainingBroken = false;
  #lineage = 0;
  #checkpoint: ProviderCheckpoint | null = null;
  #retiredCheckpoints: ProviderCheckpoint[] = [];
  /** Function-call ids the published previousResponseId still requires outputs for. */
  #outstandingToolCallIds: string[] = [];

  get previousResponseId(): string | null {
    return this.#previousResponseId;
  }

  get chainingBroken(): boolean {
    return this.#chainingBroken;
  }

  get checkpoint(): ProviderCheckpoint | null {
    return this.#checkpoint;
  }

  get lineage(): number {
    return this.#lineage;
  }

  get retiredCheckpoints(): readonly ProviderCheckpoint[] {
    return this.#retiredCheckpoints;
  }

  /** Call ids the current chain still needs tool outputs for. */
  get outstandingToolCallIds(): readonly string[] {
    return this.#outstandingToolCallIds;
  }

  hasOutstandingToolDebt(): boolean {
    return this.#outstandingToolCallIds.length > 0;
  }

  /**
   * Replace the unpaid tool-call set for the current chain. Pass an empty
   * list when the latest terminal response left no open function calls.
   */
  replaceOutstandingToolCallIds(callIds: readonly string[]): void {
    const unique: string[] = [];
    const seen = new Set<string>();
    for (const callId of callIds) {
      if (typeof callId !== 'string' || !callId || seen.has(callId)) continue;
      seen.add(callId);
      unique.push(callId);
    }
    this.#outstandingToolCallIds = unique;
  }

  /** A new user request cannot leave the preceding response's tool debt unpaid. */
  prepareNewTurn(historyLength: number): boolean {
    const hadDebt = this.hasOutstandingToolDebt();
    if (hadDebt && this.#previousResponseId) this.clear();
    return !hadDebt && this.isChainingAvailable(historyLength);
  }

  /** Keep response identity and lineage encoding inside their protocol owner. */
  prepareRequest<T extends object>(
    options: T,
    view:
      | { kind: 'initial'; inputMode: 'delta' | 'full_history'; disableChaining?: boolean }
      | { kind: 'continuation' },
  ) {
    const request = {
      ...options,
      previousResponseId:
        view.kind === 'continuation'
          ? this.#previousResponseId
          : view.disableChaining
          ? undefined
          : view.inputMode === 'delta'
          ? this.#previousResponseId
          : null,
    };
    Object.defineProperty(request, 'providerContinuityLineage', {
      value: this.#lineage,
      enumerable: this.#lineage !== 0,
    });
    return request;
  }

  /**
   * Records a provider response observed before its terminal history is
   * committed. This deliberately does not update previousResponseId: existing
   * wire continuity remains owned by update().
   */
  observeCandidate(
    candidate: ProviderCheckpointBinding & { responseId: string; opaqueState?: unknown; lineage?: number },
  ): boolean {
    if (candidate.lineage !== undefined && candidate.lineage !== this.#lineage) {
      return false;
    }
    this.#retireCheckpoint('superseded');
    this.#checkpoint = {
      ...candidate,
      lineage: this.#lineage,
      state: 'candidate',
    };
    return true;
  }

  /**
   * Accepts only the candidate for this exact terminal response and binding.
   * Call this in the same current-generation callback that committed history.
   */
  promoteCandidate(responseId: string | null, binding?: ProviderCheckpointBinding): boolean {
    const checkpoint = this.#checkpoint;
    if (
      !checkpoint ||
      checkpoint.state !== 'candidate' ||
      checkpoint.lineage !== this.#lineage ||
      checkpoint.responseId !== responseId
    ) {
      return false;
    }
    if (binding) {
      const retirement = ProviderContinuity.#bindingMismatch(checkpoint, binding);
      if (retirement) {
        this.#retireCheckpoint(retirement);
        return false;
      }
    }
    this.#checkpoint = { ...checkpoint, state: 'accepted' };
    return true;
  }

  update(responseId: string | null): void {
    this.#previousResponseId = responseId;
  }

  /**
   * Publishes the terminal response ID using the established legacy state and,
   * only after an authoritative history commit, accepts a matching observed
   * checkpoint as corroborating evidence. This does not select a checkpoint
   * for a future request.
   */
  publishTerminalResponse(
    responseId: string | null,
    historyCommitted: boolean,
    postCommitSnapshot?: ProviderCheckpointSuccessorProof,
  ): boolean {
    this.update(responseId);
    const promoted = historyCommitted && this.promoteCandidate(responseId);
    if (promoted && postCommitSnapshot) {
      this.#attachSuccessorProof(postCommitSnapshot);
    }
    return promoted;
  }

  /**
   * Synchronous, in-memory protocol update. Record acceptance has already
   * happened; diagnostics cannot undo it or turn it into a replayable failure.
   */
  acceptSegment(segment: AcceptedProviderSegment, observer?: OpenAIRootCheckpointLifecycleObserver): void {
    const hadCandidate = this.#checkpoint?.state === 'candidate';
    let promoted = false;
    if (segment.kind === 'committed') {
      promoted = this.publishTerminalResponse(segment.lastResponseId, segment.historyCommitted, segment.snapshot);
    } else this.update(segment.lastResponseId);
    this.replaceOutstandingToolCallIds(segment.unsettledToolCallIds);
    if (segment.kind === 'committed' && hadCandidate) {
      try {
        observer?.publication(
          !segment.historyCommitted ? 'history_not_committed' : promoted ? 'promoted' : 'candidate_not_promoted',
        );
      } catch {
        // Observability must not reject an accepted external effect.
      }
    }
  }

  /**
   * Pure, fail-closed characterization for a future OpenAI-private selector.
   * A successor must preserve the committed transcript exactly and add to it;
   * this does not select or publish a previous response ID.
   */
  isEligibleForSuccessor(
    identity: ProviderCheckpointIdentity,
    lineage: number,
    plannedSnapshot: ProviderCheckpointSuccessorProof,
  ): boolean {
    return this.assessSuccessorEligibility(identity, lineage, plannedSnapshot).eligible;
  }

  /**
   * Read-only, fail-closed eligibility assessment for bounded diagnostics.
   * Its fixed failure enum contains no provider IDs, history, or request data.
   */
  assessSuccessorEligibility(
    identity: ProviderCheckpointIdentity,
    lineage: number,
    plannedSnapshot: ProviderCheckpointSuccessorProof,
  ): ProviderSuccessorEligibility {
    const checkpoint = this.#checkpoint;
    const proof = checkpoint?.successorProof;
    if (!checkpoint || checkpoint.state !== 'accepted') return { eligible: false, failure: 'no_accepted_checkpoint' };
    if (checkpoint.lineage !== lineage) return { eligible: false, failure: 'lineage_mismatch' };
    if (!proof) return { eligible: false, failure: 'missing_successor_proof' };
    if (!ProviderContinuity.#isSnapshotProof(plannedSnapshot)) {
      return { eligible: false, failure: 'invalid_planned_snapshot' };
    }
    if (!ProviderContinuity.#identityMatches(checkpoint.identity, identity)) {
      return { eligible: false, failure: 'identity_mismatch' };
    }
    if (!proof.origin || proof.origin !== plannedSnapshot.origin)
      return { eligible: false, failure: 'origin_mismatch' };
    if (plannedSnapshot.revision <= proof.revision) return { eligible: false, failure: 'revision_not_advanced' };
    if (plannedSnapshot.history.length <= proof.history.length)
      return { eligible: false, failure: 'history_not_extended' };
    try {
      return proof.history.every((item, index) => isDeepStrictEqual(item, plannedSnapshot.history[index]))
        ? { eligible: true }
        : { eligible: false, failure: 'history_prefix_mismatch' };
    } catch {
      return { eligible: false, failure: 'history_prefix_mismatch' };
    }
  }

  clear(): void {
    this.#previousResponseId = null;
    this.#outstandingToolCallIds = [];
    this.#retireCheckpoint('reset');
    this.#lineage++;
  }

  breakChaining(): void {
    this.#previousResponseId = null;
    this.#outstandingToolCallIds = [];
    this.#chainingBroken = true;
    this.#retireCheckpoint('chaining_broken');
  }

  isChainingAvailable(historyLength?: number): boolean {
    return !this.#chainingBroken && (this.#previousResponseId !== null || (historyLength ?? 0) <= 1);
  }

  #retireCheckpoint(code: ProviderCheckpointRetirement['code']): void {
    if (!this.#checkpoint) return;
    this.#retiredCheckpoints.push({ ...this.#checkpoint, state: 'retired', retirement: { code } });
    this.#checkpoint = null;
  }

  #attachSuccessorProof(snapshot: ProviderCheckpointSuccessorProof): void {
    const checkpoint = this.#checkpoint;
    if (!checkpoint || checkpoint.state !== 'accepted') return;
    try {
      const proof = ProviderContinuity.#freezeSnapshot(snapshot);
      this.#checkpoint = { ...checkpoint, successorProof: proof };
    } catch {
      // This is characterization evidence only. A cloning failure must not
      // change the already-established terminal publication behavior.
    }
  }

  static #freezeSnapshot(snapshot: ProviderCheckpointSuccessorProof): ProviderCheckpointSuccessorProof {
    return Object.freeze({
      revision: snapshot.revision,
      identity: snapshot.identity,
      origin: snapshot.origin,
      history: ProviderContinuity.#deepFreeze(structuredClone(snapshot.history)),
    });
  }

  static #deepFreeze<T>(value: T, seen = new WeakSet<object>()): T {
    if (!value || typeof value !== 'object' || seen.has(value as object)) return value;
    seen.add(value as object);
    for (const child of Object.values(value as object)) ProviderContinuity.#deepFreeze(child, seen);
    return Object.freeze(value);
  }

  static #identityMatches(left: ProviderCheckpointIdentity, right: ProviderCheckpointIdentity): boolean {
    return left.provider === right.provider && left.endpoint === right.endpoint && left.model === right.model;
  }

  static #isSnapshotProof(value: unknown): value is ProviderCheckpointSuccessorProof {
    const snapshot = value as Partial<ProviderCheckpointSuccessorProof> | null;
    return !!(
      snapshot &&
      Number.isSafeInteger(snapshot.revision) &&
      typeof snapshot.identity === 'string' &&
      snapshot.identity.length > 0 &&
      typeof snapshot.origin === 'string' &&
      snapshot.origin.length > 0 &&
      Array.isArray(snapshot.history)
    );
  }

  static #bindingMismatch(
    left: ProviderCheckpointBinding,
    right: ProviderCheckpointBinding,
  ): ProviderCheckpointRetirement['code'] | null {
    if (!ProviderContinuity.#identityMatches(left.identity, right.identity)) {
      return 'identity_mismatch';
    }
    if (left.prefix.revision !== right.prefix.revision || left.prefix.identity !== right.prefix.identity) {
      return 'prefix_mismatch';
    }
    return null;
  }
}

import type { SavedToolExecution } from '../tool-execution-ledger.js';
import type { AssistantJournalItemLogEvent } from '../logging/conversation-log-events.js';
import type {
  PersistedAssistantTurnItem,
  PersistedToolCallItem,
  PersistedToolResultItem,
} from './conversation-persistence-types.js';
import { normalizeRunItems } from './run-item-normalizer.js';

const clone = <T>(value: T): T => {
  try {
    return structuredClone(value);
  } catch {
    return JSON.parse(JSON.stringify(value)) as T;
  }
};

const makeHistoryItemForToolCall = (item: PersistedToolCallItem): unknown => {
  const raw = item.providerItem;
  if (raw && typeof raw === 'object') {
    return clone(raw);
  }
  return {
    type: 'function_call',
    callId: item.callId,
    name: item.toolName,
    arguments: item.arguments,
  };
};

const makeHistoryItemForToolResult = (item: PersistedToolResultItem): unknown => {
  const raw = item.providerItem;
  if (raw && typeof raw === 'object') {
    return clone(raw);
  }
  return {
    type: 'function_call_result',
    callId: item.callId,
    name: item.toolName,
    output: item.output,
  };
};

const makeHistoryItemForReasoning = (item: Extract<PersistedAssistantTurnItem, { type: 'reasoning' }>): unknown => {
  const providerData = item.providerMetadata ? clone(item.providerMetadata) : undefined;
  if (providerData && 'reasoning_content' in providerData) {
    delete providerData.reasoning_content;
  }

  return {
    type: 'reasoning',
    ...(item.providerItemId ? { id: item.providerItemId } : {}),
    content: item.text ? [{ type: 'reasoning_text', text: item.text }] : [],
    rawContent: item.text ? [{ type: 'reasoning_text', text: item.text }] : [],
    ...(providerData && Object.keys(providerData).length > 0 ? { providerData } : {}),
  };
};

const withMissingReasoningPrefix = (historyItems: unknown[] | undefined, reasoningItems: unknown[]): unknown[] => {
  const existing = historyItems ?? [];
  if (reasoningItems.length === 0 || normalizeRunItems(existing).some((item) => item.type === 'reasoning')) {
    return existing;
  }
  return [...reasoningItems, ...existing];
};

const hasToolResultForCall = (historyItems: readonly unknown[], callId: string): boolean =>
  normalizeRunItems(historyItems).some((item) => item.type === 'tool_result' && item.callId === callId);

const appendToolResultIfMissing = (
  historyItems: unknown[] | undefined,
  callId: string,
  resultItem: unknown,
): unknown[] => {
  const existing = historyItems ?? [];
  return hasToolResultForCall(existing, callId) ? existing : [...existing, resultItem];
};

/**
 * Reconstructs tool-execution ledger entries from persisted assistant turn
 * items. This lets the durable journal serve as the source of truth for
 * recovery instead of the legacy in-memory ledger.
 */
export function buildToolLedgerFromAssistantTurnItems(
  items: PersistedAssistantTurnItem[],
  turnId: string,
  startedAt: string,
): SavedToolExecution[] {
  const entries: SavedToolExecution[] = [];
  const calls = new Map<string, PersistedToolCallItem>();
  let pendingReasoningHistoryItems: unknown[] = [];

  for (const item of items) {
    if (item.type === 'reasoning') {
      pendingReasoningHistoryItems.push(makeHistoryItemForReasoning(item));
      continue;
    }

    if (item.type === 'tool_call') {
      calls.set(item.callId, item);
      const callHistoryItem = makeHistoryItemForToolCall(item);
      const existing = entries.find((entry) => entry.callId === item.callId);
      if (!existing) {
        entries.push({
          turnId,
          callId: item.callId,
          toolName: item.toolName,
          arguments: item.arguments,
          status: 'started',
          startedAt,
          historyItems: [...pendingReasoningHistoryItems, callHistoryItem].filter(Boolean) as unknown[],
        });
      } else {
        existing.toolName = item.toolName;
        existing.arguments = item.arguments;
        if (!existing.historyItems || existing.historyItems.length === 0) {
          existing.historyItems = [...pendingReasoningHistoryItems, callHistoryItem].filter(Boolean) as unknown[];
        } else {
          existing.historyItems = withMissingReasoningPrefix(existing.historyItems, pendingReasoningHistoryItems);
        }
      }
      pendingReasoningHistoryItems = [];
      continue;
    }

    pendingReasoningHistoryItems = [];

    if (item.type !== 'tool_result') {
      continue;
    }

    let existing = entries.find((entry) => entry.callId === item.callId);
    if (!existing) {
      const call = calls.get(item.callId);
      existing = {
        turnId,
        callId: item.callId,
        toolName: item.toolName,
        arguments: call?.arguments,
        status: 'started',
        startedAt,
        historyItems: call ? [makeHistoryItemForToolCall(call)] : [],
      };
      entries.push(existing);
    }

    const callHistoryItem = existing.historyItems?.find((historyItem) =>
      normalizeRunItems([historyItem]).some((normalizedItem) => normalizedItem.type === 'tool_call'),
    );
    existing.toolName = item.toolName;
    existing.status = item.status;
    existing.output = item.output;
    existing.completedAt = startedAt;
    const previousHistoryItems = existing.historyItems ?? (callHistoryItem ? [callHistoryItem] : []);
    existing.historyItems = appendToolResultIfMissing(
      previousHistoryItems,
      item.callId,
      makeHistoryItemForToolResult(item),
    ).filter(Boolean) as unknown[];
  }

  return entries;
}

/**
 * Reconstructs tool-execution ledger entries from journal item events,
 * preserving the original turn ids. Prefer this over
 * {@link buildToolLedgerFromAssistantTurnItems} when recovering from the
 * live journal so multi-turn history stays correctly ordered.
 */
export function buildToolLedgerFromJournalEvents(
  events: AssistantJournalItemLogEvent[],
  startedAt: string,
): SavedToolExecution[] {
  const entriesByTurn = new Map<string, SavedToolExecution[]>();
  const pendingReasoningByTurn = new Map<string, unknown[]>();

  for (const event of events) {
    const turnEntries = entriesByTurn.get(event.turnId) ?? [];
    entriesByTurn.set(event.turnId, turnEntries);
    const pendingReasoning = pendingReasoningByTurn.get(event.turnId) ?? [];
    pendingReasoningByTurn.set(event.turnId, pendingReasoning);

    const item = event.item;
    if (item.type === 'reasoning') {
      pendingReasoning.push(makeHistoryItemForReasoning(item));
      continue;
    }

    if (item.type === 'tool_call') {
      const existing = turnEntries.find((entry) => entry.callId === item.callId);
      const callHistoryItem = makeHistoryItemForToolCall(item);
      if (!existing) {
        turnEntries.push({
          turnId: event.turnId,
          callId: item.callId,
          toolName: item.toolName,
          arguments: item.arguments,
          status: 'started',
          startedAt,
          historyItems: [...pendingReasoning, callHistoryItem].filter(Boolean) as unknown[],
        });
      } else {
        existing.toolName = item.toolName;
        existing.arguments = item.arguments;
        if (!existing.historyItems || existing.historyItems.length === 0) {
          existing.historyItems = [...pendingReasoning, callHistoryItem].filter(Boolean) as unknown[];
        } else {
          existing.historyItems = withMissingReasoningPrefix(existing.historyItems, pendingReasoning);
        }
      }
      pendingReasoning.length = 0;
      continue;
    }

    pendingReasoning.length = 0;

    if (item.type === 'tool_result') {
      let existing = turnEntries.find((entry) => entry.callId === item.callId);
      if (!existing) {
        existing = {
          turnId: event.turnId,
          callId: item.callId,
          toolName: item.toolName,
          arguments: undefined,
          status: 'started',
          startedAt,
          historyItems: [],
        };
        turnEntries.push(existing);
      }
      existing.toolName = item.toolName;
      existing.status = item.status;
      existing.output = item.output;
      existing.completedAt = startedAt;
      const previousHistoryItems = existing.historyItems ?? [];
      existing.historyItems = appendToolResultIfMissing(
        previousHistoryItems,
        item.callId,
        makeHistoryItemForToolResult(item),
      ).filter(Boolean) as unknown[];
    }
  }

  return [...entriesByTurn.values()].flat();
}

